101	/** Copy all mirrored fields from flat state → tab (for tab switching). */
102	function syncTabStateFromFlat(draft: ChatState, tab: 'think' | 'do') {
103	  draft[tab].sessionId = draft.sessionId;
104	  draft[tab].messages = draft.messages;
105	  draft[tab].isStreaming = draft.isStreaming;
106	  draft[tab].isCompacting = draft.isCompacting;
107	  draft[tab].lastStatus = draft.lastStatus;
