154	export interface ChatState {
155	  sessionId: string | null;
156	  messages: ChatMessage[];
157	  isStreaming: boolean;
158	  isCompacting: boolean;
159	  handshakeReceived: boolean;
160	  draftMedia: DraftMediaItem[];
