191	  respondQuestion: (answers: Record<string, string>) => Promise<void>;
192	  setTitle: (sessionId: string | null, title: string, source: TitleSource) => void;
193	  renameSession: (sessionId: string, newTitle: string) => Promise<void>;
194	
195	  enqueue: (content: string | ContentPart[], model: string) => void;
196	  removeFromQueue: (id: string) => void;
