 17	function formatRelativeDate(timestamp: number): string {
 18	  const diff = Date.now() - timestamp;
 19	  const m = Math.floor(diff / 60000);
 20	  const h = Math.floor(diff / 3600000);
 21	  const d = Math.floor(diff / 86400000);
 22	  if (m < 1) return "Just now";
 23	  if (m < 60) return `${m}m ago`;
 24	  if (h < 24) return `${h}h ago`;
 25	  if (d < 7) return `${d}d ago`;
 26	  return new Date(timestamp).toLocaleDateString();
 27	}
