 10	function getNonce(): string {
 11	  const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
 12	  let nonce = "";
 13	  for (let i = 0; i < 32; i++) {
 14	    nonce += chars.charAt(Math.floor(Math.random() * chars.length));
 15	  }
 16	  return nonce;
 17	}
