 20	 * Manages webview instances (sidebar and panels).
 21	 * Each webview gets a unique viewId for session isolation.
 22	 */
 23	export class ConsiliumWebviewProvider implements vscode.WebviewViewProvider {
 24	  private webviews = new Map<string, vscode.Webview>();
 25	  private bridgeHandler: BridgeHandler;
 26	
 27	  constructor(
 28	    private readonly extensionUri: vscode.Uri,
 29	    workspaceState: vscode.Memento,
 30	    globalState: vscode.Memento,
 31	    showLogs: () => void,
 32	  ) {
 33	    this.bridgeHandler = new BridgeHandler(this.broadcastInternal.bind(this), workspaceState, globalState, this.reloadWebview.bind(this), showLogs, this.extensionUri.fsPath);
 34	  }
 35	
 36	  dispose(): void {
 37	    this.bridgeHandler.dispose();
 38	  }
 39	
 40	  /** Clean up per-webview resources (broadcast queue, etc.). Must be called before bridgeHandler.disposeView. */
 41	  disposeView(webviewId: string): void {
 42	    this.broadcastQueues.delete(webviewId);
 43	    if (this.broadcastTimeout && this.broadcastQueues.size === 0) {
 44	      clearTimeout(this.broadcastTimeout);
 45	      this.broadcastTimeout = null;
 46	    }
 47	  }
 48	
 49	  resolveWebviewView(webviewView: vscode.WebviewView): void {
 50	    const webviewId = `sidebar_${crypto.randomUUID()}`;
 51	    this.setupWebview(webviewId, webviewView.webview);
 52	
 53	    webviewView.onDidDispose(async () => {
 54	      this.disposeView(webviewId);
 55	      await this.bridgeHandler.disposeView(webviewId);
 56	      this.webviews.delete(webviewId);
 57	    });
 58	  }
 59	
 60	  createPanel(): vscode.WebviewPanel {
 61	    const webviewId = `panel_${crypto.randomUUID()}`;
 62	
 63	    const panel = vscode.window.createWebviewPanel("consiliumPanel", "Consilium", vscode.ViewColumn.One, {
 64	      enableScripts: true,
 65	      retainContextWhenHidden: true,
 66	      localResourceRoots: [this.extensionUri],
 67	    });
 68	
 69	    this.setupWebview(webviewId, panel.webview);
 70	
 71	    panel.onDidDispose(async () => {
 72	      this.disposeView(webviewId);
 73	      await this.bridgeHandler.disposeView(webviewId);
 74	      this.webviews.delete(webviewId);
 75	    });
 76	
 77	    return panel;
 78	  }
 79	
 80	  broadcast(event: string, data: unknown): void {
 81	    this.broadcastInternal(event, data);
 82	  }
 83	
 84	  private setupWebview(webviewId: string, webview: vscode.Webview): void {
 85	    webview.options = {
 86	      enableScripts: true,
 87	      localResourceRoots: [this.extensionUri],
 88	    };
 89	
 90	    webview.html = this.getHtml(webviewId, webview);
 91	    this.webviews.set(webviewId, webview);
 92	
 93	    webview.onDidReceiveMessage(async (msg: RpcMessage & { webviewId?: string }) => {
 94	      const result = await this.bridgeHandler.handle(msg, webviewId);
 95	      webview.postMessage(result);
 96	    });
 97	  }
 98	
 99	  private broadcastQueues = new Map<string, { event: string; data: unknown }[]>();
100	  private broadcastTimeout: NodeJS.Timeout | null = null;
101	
102	  private broadcastInternal(event: string, data: unknown, targetWebviewId?: string): void {
103	    const msg = { event, data };
104	    const targets = targetWebviewId ? [targetWebviewId] : Array.from(this.webviews.keys());
105	
106	    for (const target of targets) {
107	      let queue = this.broadcastQueues.get(target);
108	      if (!queue) {
109	        queue = [];
110	        this.broadcastQueues.set(target, queue);
111	      }
112	      queue.push(msg);
113	    }
114	
115	    if (!this.broadcastTimeout) {
116	      this.broadcastTimeout = setTimeout(() => this.flushBroadcast(), 50);
117	    }
118	  }
119	
120	  private flushBroadcast(): void {
121	    this.broadcastTimeout = null;
122	    for (const [target, queue] of this.broadcastQueues.entries()) {
123	      if (queue.length > 0) {
124	        const webview = this.webviews.get(target);
125	        if (webview) {
126	          webview.postMessage(queue);
127	        }
128	        this.broadcastQueues.set(target, []);
129	      }
130	    }
131	  }
132	
133	  private reloadWebview(webviewId: string): void {
134	    const webview = this.webviews.get(webviewId);
135	    if (webview) {
136	      webview.html = this.getHtml(webviewId, webview);
137	    }
138	  }
139	
140	  reloadAllWebviews(): void {
141	    this.webviews.forEach((webview, webviewId) => {
142	      webview.html = this.getHtml(webviewId, webview);
143	    });
144	  }
145	
146	  private getHtml(webviewId: string, webview: vscode.Webview): string {
147	    const scriptUri = webview.asWebviewUri(vscode.Uri.joinPath(this.extensionUri, "dist", "webview.js"));
148	    const baseUri = webview.asWebviewUri(this.extensionUri).toString();
149	    const nonce = getNonce();
150	
151	    const csp = [
152	      `default-src 'none'`,
153	      `style-src ${webview.cspSource} 'unsafe-inline'`,
154	      `img-src ${webview.cspSource} data: blob:`,
155	      `font-src ${webview.cspSource}`,
156	      `media-src ${webview.cspSource} data: blob:`,
157	      `connect-src ${webview.cspSource}`,
158	      `worker-src ${webview.cspSource} blob:`,
159	      `script-src 'nonce-${nonce}' ${webview.cspSource}`,
160	    ].join("; ");
161	
162	    return `<!DOCTYPE html>
163	<html lang="en">
164	<head>
165	  <meta charset="UTF-8">
166	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
167	  <meta http-equiv="Content-Security-Policy" content="${csp}">
168	  <title>Consilium</title>
169	</head>
170	<body data-baseuri="${baseUri}" data-webviewid="${webviewId}">
171	  <div id="root"></div>
172	  <script nonce="${nonce}" src="${scriptUri}"></script>
173	</body>
174	</html>`;
175	  }
176	}

