 20	class Bridge {
 21	  private vscode: VSCodeAPI;
 22	  private pending = new Map<string, PendingRequest>();
 23	  private eventHandlers = new Map<string, Set<(data: unknown) => void>>();
 24	  private requestId = 0;
 25	  private webviewId: string;
 26	
 27	  constructor() {
 28	    this.webviewId = document.body.getAttribute("data-webviewid") || `unknown_${Date.now()}`;
 29	
 30	    if (typeof acquireVsCodeApi === "function") {
 31	      this.vscode = acquireVsCodeApi();
 32	    } else {
 33	      console.warn("[Consilium Bridge] Running outside VS Code, using mock");
 34	      this.vscode = {
 35	        postMessage: (msg) => console.log("[Consilium Mock]", msg),
 36	        getState: () => undefined,
 37	        setState: () => {},
 38	      };
 39	    }
 40	
 41	    window.addEventListener("message", this.handleMessage);
 42	  }
 43	
 44	  private handleMessage = (event: MessageEvent) => {
 45	    const processMsg = (msg: any) => {
 46	      if (msg.id && this.pending.has(msg.id)) {
 47	        const { resolve, reject, timeout } = this.pending.get(msg.id)!;
 48	        clearTimeout(timeout);
 49	        this.pending.delete(msg.id);
 50	
 51	        if (msg.error) {
 52	          reject(new Error(msg.error));
 53	        } else {
 54	          resolve(msg.result);
 55	        }
 56	        return;
 57	      }
 58	
 59	      if (msg.event) {
 60	        const handlers = this.eventHandlers.get(msg.event);
 61	        handlers?.forEach((h) => h(msg.data));
 62	      }
 63	    };
 64	
 65	    if (Array.isArray(event.data)) {
 66	      event.data.forEach(processMsg);
 67	    } else {
 68	      processMsg(event.data);
 69	    }
 70	  };
 71	
 72	  private call<T>(method: string, params?: unknown): Promise<T> {
 73	    const id = `${++this.requestId}_${Date.now()}`;
 74	
 75	    return new Promise((resolve, reject) => {
 76	      const timeout = setTimeout(() => {
 77	        this.pending.delete(id);
 78	        reject(new Error(`Bridge ${method} timed out`));
 79	      }, 600000);
 80	
 81	      this.pending.set(id, { resolve: resolve as (v: unknown) => void, reject, timeout });
 82	      this.vscode.postMessage({ id, method, params, webviewId: this.webviewId });
 83	    });
 84	  }
 85	
 86	  on<T>(event: string, handler: (data: T) => void): () => void {
 87	    if (!this.eventHandlers.has(event)) {
 88	      this.eventHandlers.set(event, new Set());
 89	    }
 90	    this.eventHandlers.get(event)!.add(handler as (data: unknown) => void);
 91	
 92	    return () => {
 93	      this.eventHandlers.get(event)?.delete(handler as (data: unknown) => void);
 94	    };
 95	  }
