 44	function findToolUseItem(steps: UIStep[], toolId: string): (UIStepItem & { type: "tool_use" }) | null {
 45	  for (const step of steps) {
 46	    for (const item of step.items) {
 47	      if (item.type === "tool_use") {
 48	        if (item.id === toolId) {
 49	          return item;
 50	        }
 51	
 52	        if (item.subagent_steps) {
 53	          const found = findToolUseItem(item.subagent_steps, toolId);
 54	          if (found) {
 55	            return found;
 56	          }
 57	        }
 58	      }
 59	    }
 60	  }
 61	
 62	  return null;
