267	function handlePreflightError(draft: ChatState, code: string, message: string): void {
268	  // Pre-flight: 删除未发送成功的消息，恢复输入
269	  addTokenUsage(draft.tokenUsage, draft.activeTokenUsage);
270	  draft.activeTokenUsage = createEmptyTokenUsage();
271	  draft.isStreaming = false;
272	  draft.isCompacting = false;
273	  useApprovalStore.getState().clearRequests();
274	
275	  // 删除空的 assistant 消息
276	  const lastAssistant = getLastAssistant(draft);
277	  if (lastAssistant && !hasContent(lastAssistant)) {
278	    draft.messages.pop();
279	  }
280	
281	  // 删除对应的 user 消息
282	  const lastUser = draft.messages.at(-1);
283	  if (lastUser?.role === "user") {
284	    const userContent = lastUser.content;
285	    draft.messages.pop();
286	    // 触发回滚（通过 pendingInput 保存）
287	    draft.pendingInput = { content: userContent, model: "" };
288	  }
289	}
