311	const eventHandlers: Record<string, EventHandler> = {
312	  // UI 事件 (Bridge 层)
313	  session_start: (draft, payload: { sessionId: string; model?: string; mode?: 'think' | 'do' }) => {
314	    if (payload.sessionId) {
315	      draft.sessionId = payload.sessionId;
316	      const tab = payload.mode ?? (draft.activeTab === 'do' ? 'do' : 'think');
317	      draft[tab].sessionId = payload.sessionId;
318	    }
319	  },
320	
321	  stream_complete: (draft, payload: { result: RunResult }) => {
322	    addTokenUsage(draft.tokenUsage, draft.activeTokenUsage);
323	    draft.activeTokenUsage = createEmptyTokenUsage();
324	    draft.isStreaming = false;
325	    draft.isCompacting = false;
326	    draft.pendingInput = null;
327	    useApprovalStore.getState().clearRequests();
328	    const lastAssistant = getLastAssistant(draft);
329	    if (lastAssistant?.steps) {
330	      finishAllTextItems(lastAssistant.steps);
331	      if ((payload.result as any)?.status === "interrupted") {
332	        markPendingToolsAsCancelled(lastAssistant.steps);
333	      }
334	    }
335	  },
336	
337	  error: (draft, payload: StreamError) => {
338	    const code = payload.code || "UNKNOWN";
339	    const phase = payload.phase || (isPreflightError(code) ? "preflight" : "runtime");
340	
341	    if (code === "UNKNOWN_EVENT_TYPE") {
342	      return;
343	    } // 忽略未知事件类型错误，通常是版本不匹配导致
344	
345	    if (phase === "preflight") {
346	      handlePreflightError(draft, code, payload.message);
347	    } else {
348	      if (isUserInterrupt(code)) {
349	        addTokenUsage(draft.tokenUsage, draft.activeTokenUsage);
350	        draft.activeTokenUsage = createEmptyTokenUsage();
351	        draft.isStreaming = false;
352	        draft.isCompacting = false;
353	        useApprovalStore.getState().clearRequests();
354	        const lastAssistant = getLastAssistant(draft);
355	        if (lastAssistant?.steps) {
356	          finishAllTextItems(lastAssistant.steps);
357	          markPendingToolsAsCancelled(lastAssistant.steps);
358	        }
359	      } else {
360	        handleRuntimeError(draft, code, payload.message, payload.detail);
361	      }
362	    }
363	  },
364	
365	  // Wire 事件
366	  TurnBegin: (draft, payload: TurnBegin) => {
367	    draft.tokenUsage = createEmptyTokenUsage();
368	    draft.activeTokenUsage = createEmptyTokenUsage();
369	
370	    draft.messages.push({
371	      id: crypto.randomUUID(),
372	      role: "user",
373	      content: payload.user_input,
374	      timestamp: Date.now(),
375	    });
376	
377	    draft.messages.push({
378	      id: crypto.randomUUID(),
379	      role: "assistant",
380	      content: "",
381	      timestamp: Date.now(),
382	      steps: [],
383	    });
384	
385	    draft.isStreaming = true;
386	  },
387	
388	  Message: (draft, payload: { role: string; content: any }) => {
389	    draft.messages.push({
390	      id: crypto.randomUUID(),
391	      role: payload.role as any,
392	      content: payload.content,
393	      timestamp: Date.now(),
394	      steps: [],
395	    });
396	  },
397	
398	  CompactionBegin: (draft) => {
399	    draft.isCompacting = true;
400	
401	    const last = getLastAssistant(draft);
402	
403	    if (last) {
404	      if (!last.steps) {
405	        last.steps = [];
406	      }
407	
408	      if (last.steps.length === 0) {
409	        last.steps.push({ n: 0, items: [] });
410	      }
411	
412	      finishAllTextItems(last.steps);
413	      last.steps.at(-1)!.items.push({ type: "compaction" });
414	    }
415	  },
416	
417	  CompactionEnd: (draft) => {
418	    draft.isCompacting = false;
419	  },
420	
421	  StepBegin: (draft, payload) => {
422	    const last = getLastAssistant(draft);
423	
424	    if (last) {
425	      if (!last.steps) {
426	        last.steps = [];
427	      }
428	
429	      applyEventToSteps(last.steps, { type: "StepBegin", payload });
430	
431	      // Tag the newly created step with current plan mode state
432	      // Note: only top-level steps get tagged. Subagent steps go through
433	      // SubagentEvent -> applyEventToSteps and won't inherit main agent's planMode.
434	      const newStep = last.steps.at(-1);
435	      if (newStep && draft.planMode) {
436	        newStep.planMode = true;
437	      }
438	    }
439	  },
440	
441	  StepInterrupted: (draft) => {
442	    addTokenUsage(draft.tokenUsage, draft.activeTokenUsage);
443	    draft.activeTokenUsage = createEmptyTokenUsage();
444	
445	    draft.isStreaming = false;
446	    useApprovalStore.getState().clearRequests();
447	    const lastAssistant = getLastAssistant(draft);
448	    if (lastAssistant?.steps) {
449	      finishAllTextItems(lastAssistant.steps);
450	      markPendingToolsAsCancelled(lastAssistant.steps);
451	    }
452	  },
453	
454	  TurnEnd: (draft) => {
455	    // TurnEnd signals the assistant turn has ended. Reset streaming state
456	    // immediately so the UI doesn't stay stuck in "Processing" if the
457	    // subsequent stream_complete is delayed or dropped during a tab switch.
458	    draft.isStreaming = false;
459	    const lastAssistant = getLastAssistant(draft);
460	    if (lastAssistant?.steps) {
461	      finishAllTextItems(lastAssistant.steps);
462	    }
463	  },
464	
465	  ContentPart: (draft, payload: ContentPart) => {
466	    const last = getLastAssistant(draft);
467	    if (!last?.steps) {
468	      return;
469	    }
470	
471	    applyEventToSteps(last.steps, { type: "ContentPart", payload }, (text) => {
472	      if (typeof last.content === "string") {
473	        last.content += text;
474	      }
475	    });
476	  },
477	
478	  ToolCall: (draft, payload: ToolCall) => {
479	    const last = getLastAssistant(draft);
480	    if (!last?.steps) {
481	      return;
482	    }
483	    applyEventToSteps(last.steps, { type: "ToolCall", payload });
484	  },
485	
486	  ToolCallPart: (draft, payload) => {
487	    const last = getLastAssistant(draft);
488	    if (!last?.steps) {
489	      return;
490	    }
491	    applyEventToSteps(last.steps, { type: "ToolCallPart", payload });
492	  },
493	
494	  ToolResult: (draft, payload: ToolResult) => {
495	    const last = getLastAssistant(draft);
496	    if (!last?.steps) {
497	      return;
498	    }
499	
500	    if (isTaskToolResult(last.steps, payload.tool_call_id)) {
501	      addTokenUsage(draft.tokenUsage, draft.activeTokenUsage);
502	      draft.activeTokenUsage = createEmptyTokenUsage();
503	    }
504	
505	    applyEventToSteps(last.steps, { type: "ToolResult", payload });
506	  },
507	
508	  SubagentEvent: (draft, payload: SubagentEvent) => {
509	    const last = getLastAssistant(draft);
510	    if (!last?.steps) {
511	      return;
512	    }
513	
514	    const target = resolveSubagentTarget(last.steps, payload);
515	    if (!target) {
516	      return;
517	    }
518	
519	    if (target.event.type === "StatusUpdate") {
520	      const { token_usage } = target.event.payload;
521	
522	      if (token_usage) {
523	        addTokenUsage(draft.activeTokenUsage, {
524	          input_other: token_usage.input_other || 0,
525	          output: token_usage.output || 0,
526	          input_cache_read: token_usage.input_cache_read || 0,
527	          input_cache_creation: token_usage.input_cache_creation || 0,
528	        });
529	      }
530	
531	      return;
532	    }
533	
534	    // Nested Subagent Task End: accumulate token usage
535	    if (target.event.type === "ToolResult") {
536	      const toolResultPayload = target.event.payload as ToolResult;
537	      if (isTaskToolResult(target.steps, toolResultPayload.tool_call_id)) {
538	        addTokenUsage(draft.tokenUsage, draft.activeTokenUsage);
539	        draft.activeTokenUsage = createEmptyTokenUsage();
540	      }
541	    }
542	
543	    applyEventToSteps(target.steps, target.event);
544	  },
545	
546	  ApprovalRequest: (_, payload: ApprovalRequestPayload) => {
547	    useApprovalStore.getState().addRequest({
548	      id: payload.id,
549	      tool_call_id: payload.tool_call_id,
550	      sender: payload.sender,
551	      action: payload.action,
552	      description: payload.description,
553	      display: payload.display ?? [],
554	    });
555	  },
556	
557	  QuestionRequest: (draft, payload: QuestionRequest) => {
558	    draft.pendingQuestion = payload;
559	  },
560	
561	  StatusUpdate: (draft, payload) => {
562	    const { context_usage, token_usage, plan_mode } = payload;
563	
564	    if (plan_mode !== undefined && plan_mode !== null) {
565	      draft.planMode = plan_mode;
566	    }
567	
568	    if (token_usage) {
569	      addTokenUsage(draft.activeTokenUsage, {
570	        input_other: token_usage.input_other || 0,
571	        output: token_usage.output || 0,
572	        input_cache_read: token_usage.input_cache_read || 0,
573	        input_cache_creation: token_usage.input_cache_creation || 0,
574	      });
575	    }
576	
577	    draft.lastStatus = { context_usage, token_usage };
578	
579	    const last = getLastAssistant(draft);
580	
581	    if (last) {
582	      last.status = draft.lastStatus;
583	    }
584	  },
585	
586	  SteerInput: (draft, payload: { user_input: string | ContentPart[] }) => {
587	    const last = getLastAssistant(draft);
588	    if (!last?.steps) return;
589	
590	    const currentStep = last.steps.at(-1);
591	    if (!currentStep) return;
592	
593	    finishAllTextItems(last.steps);
594	    currentStep.items.push({ type: "steer", content: payload.user_input });
595	  },
596	};
