 1	/**
 2	 * Pure helper for routing a stream event to the correct Think/Do tab.
 3	 *
 4	 * The caller (chat.store.ts) passes the event plus a snapshot of the tab
 5	 * session IDs. The explicit `mode` field takes precedence, then we fall back
 6	 * to matching `_sessionId`, and finally to the currently active tab.
 7	 */
 8	
 9	export interface EventRoutingInfo {
10	  mode?: 'think' | 'do';
11	  _sessionId?: string;
12	}
13	
14	export interface TabStateSnapshot {
15	  activeTab: 'think' | 'do';
16	  thinkSessionId: string | null;
17	  doSessionId: string | null;
18	}
19	
20	export function getTargetTab(event: EventRoutingInfo, state: TabStateSnapshot): 'think' | 'do' {
21	  if (event.mode === 'think' || event.mode === 'do') {
22	    return event.mode;
23	  }
24	  // Active tab takes precedence when its sessionId matches; this avoids
25	  // routing events to the wrong tab if session IDs ever collide.
26	  if (state.activeTab === 'think' && state.thinkSessionId && state.thinkSessionId === event._sessionId) {
27	    return 'think';
28	  }
29	  if (state.activeTab === 'do' && state.doSessionId && state.doSessionId === event._sessionId) {
30	    return 'do';
31	  }
32	  if (state.thinkSessionId && state.thinkSessionId === event._sessionId) {
33	    return 'think';
34	  }
35	  if (state.doSessionId && state.doSessionId === event._sessionId) {
36	    return 'do';
37	  }
38	  return state.activeTab;
39	}

